CREATE FUNCTION public.create_large_object(content text) RETURNS oid
    LANGUAGE plpgsql
    AS $$
DECLARE
    loid oid;
    fd integer;
BEGIN
    loid := lo_create(0);
    fd := lo_open(loid, 131072);  -- INV_WRITE for write access
    PERFORM lowrite(fd, convert_to(content, 'UTF8'));
    PERFORM lo_close(fd);
    RETURN loid;
END;
$$;


